df['Daily_Return'] = df['Close'].pct_change()
start_price = df['Close'].iloc[0]
end_price = df['Close'].iloc[-1]
cumulative_return = (end_price / start_price - 1)
years = (df['Date'].iloc[-1] - df['Date'].iloc[0]).days / 365.25
cagr = (end_price / start_price) ** (1 / years) - 1
rolling_max = df['Close'].cummax()
drawdown = (df['Close'] - rolling_max) / rolling_max
max_drawdown = drawdown.min()
ann_vol = df['Daily_Return'].std() * (252**0.5)
avg_volume = df['Volume'].mean()
ath = df['Close'].max()
ath_date = df.loc[df['Close'].idxmax(), 'Date']
atl = df['Close'].min()
atl_date = df.loc[df['Close'].idxmin(), 'Date']

yearly = pd.read_csv('/app/output/yearly.csv')
best_year = yearly.loc[yearly['Return'].idxmax()]
worst_year = yearly.loc[yearly['Return'].idxmin()]
positive_years = (yearly['Return'] > 0).sum()
total_years = len(yearly)

# Volume era comparison
df['Era'] = pd.cut(df['Date'], bins=[pd.Timestamp('1999-12-31'), pd.Timestamp('2009-12-31'), pd.Timestamp('2019-12-31'), pd.Timestamp('2026-12-31')],
                   labels=['2000–2009', '2010–2019', '2020–2026'])
era_vol = df.groupby('Era', observed=True)['Volume'].mean()

